/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Clearing an assignee publishes `issue.unassigned`
 * instead, since `issue.assigned` carries a non-null assignee by contract;
 * clearing an issue that has no assignee publishes nothing.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    if (before.assigneeId !== null) {
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: after.id,
        projectId: after.projectId,
        previousAssigneeId: before.assigneeId,
      });
    }
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

/**
 * Clears the assignee of every live issue `userId` holds, one
 * `issue.unassigned` per issue, attributed to the `actor` doing the removal.
 * Archived issues keep their assignee. Called when a member leaves the org.
 */
export async function unassignIssuesForUser(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<number> {
  assertOrgScope(actor, orgId);

  const held = await issueRepo.listLiveIssuesAssignedTo(orgId, userId);

  for (const issue of held) {
    const after = await issueRepo.setIssueAssignee(orgId, issue.id, null);

    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId: userId,
    });
  }

  return held.length;
}

