      userId: tenant.userIds.viewer,
    });
  });

  // Removal releases the live issues the member holds, one issue.unassigned each, attributed to the remover; archived issues keep their assignee.
  it("unassigns the removed member's live issues and leaves archived ones alone", async () => {
    const tenant = await createTenant("member-remove-cascade", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const held = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Held by viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const archived = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Archived while held",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archived.id);

    const seen: TaskflowEventMap["issue.unassigned"][] = [];
    const off = subscribe("issue.unassigned", (payload) => {
      seen.push(payload);
    });
    try {
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    } finally {
      off();
    }

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      issueId: held.id,
      projectId: tenant.project.id,
      actorId: tenant.userIds.owner,
      previousAssigneeId: tenant.userIds.viewer,
    });

    const heldAfter = await issueRepo.findIssueById(tenant.org.id, held.id);
    expect(heldAfter?.assigneeId).toBeNull();
    const archivedAfter = await issueRepo.findIssueById(tenant.org.id, archived.id);
    expect(archivedAfter?.assigneeId).toBe(tenant.userIds.viewer);
  });
});

